class Solution {
public:
    int countPartitions(vector<int>& nums, int k) {
        const long long MOD = 1000000007;
        int n = nums.size();
        vector<long long> S(n + 1, 0);
        S[0] = 1; // S[i] = sum of dp[0..i], with dp[0]=1
        deque<int> maxD, minD;
        int left = 0;
        long long dp_i = 0;
        for (int i = 1; i <= n; i++) {
            int v = nums[i - 1];
            while (!maxD.empty() && nums[maxD.back()] <= v) maxD.pop_back();
            maxD.push_back(i - 1);
            while (!minD.empty() && nums[minD.back()] >= v) minD.pop_back();
            minD.push_back(i - 1);
            while (nums[maxD.front()] - nums[minD.front()] > k) {
                if (maxD.front() == left) maxD.pop_front();
                if (minD.front() == left) minD.pop_front();
                left++;
            }
            long long sub = (left >= 1) ? S[left - 1] : 0;
            dp_i = (S[i - 1] - sub + MOD) % MOD;
            S[i] = (S[i - 1] + dp_i) % MOD;
        }
        return (int)dp_i;
    }
};
